CREATE TABLE IF NOT EXISTS customer_profiles (user_id INT PRIMARY KEY, phone VARCHAR(60) NOT NULL DEFAULT '', default_address_id INT NULL, dietary_notes VARCHAR(500) NOT NULL DEFAULT '') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS customer_addresses (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,label VARCHAR(60) NOT NULL,recipient VARCHAR(150) NOT NULL,phone VARCHAR(60) NOT NULL,address TEXT NOT NULL,city VARCHAR(100) NOT NULL DEFAULT '',instructions VARCHAR(500) NOT NULL DEFAULT '',INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS customer_favourites (user_id INT NOT NULL,product_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,product_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS customer_requests (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,order_id INT NULL,kind VARCHAR(20) NOT NULL,subject VARCHAR(150) NOT NULL,message TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',reply TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS wallet_accounts (user_id INT NOT NULL,mode VARCHAR(4) NOT NULL,balance BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(user_id,mode)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS wallet_topups (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,reference VARCHAR(80) NOT NULL UNIQUE,nonce VARCHAR(64) NOT NULL UNIQUE,amount BIGINT NOT NULL,mode VARCHAR(4) NOT NULL,email VARCHAR(190) NOT NULL,secret_cipher TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'initialized',authorization_url VARCHAR(1000) NOT NULL DEFAULT '',attempted TINYINT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS wallet_ledger (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,mode VARCHAR(4) NOT NULL,amount BIGINT NOT NULL,balance_after BIGINT NOT NULL,event_key VARCHAR(120) NOT NULL UNIQUE,kind VARCHAR(20) NOT NULL,reference VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,mode,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS wallet_spends (payment_id INT PRIMARY KEY,user_id INT NOT NULL,entity_type VARCHAR(10) NOT NULL,entity_id INT NOT NULL,mode VARCHAR(4) NOT NULL,amount BIGINT NOT NULL,INDEX(entity_type,entity_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_conversations (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,customer_read_id BIGINT NOT NULL DEFAULT 0,staff_read_id BIGINT NOT NULL DEFAULT 0,customer_typing_until DATETIME NULL,staff_typing_until DATETIME NULL,staff_typing_user_id INT NULL,staff_seen_at DATETIME NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_messages (id BIGINT AUTO_INCREMENT PRIMARY KEY,conversation_id INT NOT NULL,sender_id INT NOT NULL,sender_role VARCHAR(12) NOT NULL,body TEXT NOT NULL,client_nonce VARCHAR(64) NOT NULL,created_at DATETIME NOT NULL,UNIQUE(conversation_id,sender_id,client_nonce),INDEX(conversation_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_reactions (message_id BIGINT NOT NULL,user_id INT NOT NULL,reaction VARCHAR(16) NOT NULL,PRIMARY KEY(message_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
